frappe.ui.form.on('Deal Service Item', {
    service: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.service) {
            // Получаем стандартную цену из справочника Service
            frappe.db.get_value('Service', row.service, 'standard_rate', (r) => {
                if (r && r.standard_rate) {
                    frappe.model.set_value(cdt, cdn, 'rate', r.standard_rate);
                    frappe.model.set_value(cdt, cdn, 'qty', row.qty || 1);
                    frappe.model.set_value(cdt, cdn, 'amount', r.standard_rate * (row.qty || 1));
                }
            });
        }
    },
    rate: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        frappe.model.set_value(cdt, cdn, 'amount', (row.rate || 0) * (row.qty || 1));
    },
    qty: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        frappe.model.set_value(cdt, cdn, 'amount', (row.rate || 0) * (row.qty || 1));
    }
});

frappe.ui.form.on('Deal', {
    refresh: function(frm) {
        calculate_services_total(frm);
    },
    paid_by_developer: function(frm) {
        calculate_totals(frm);
    },
    paid_by_bank: function(frm) {
        calculate_totals(frm);
    },
    paid_by_insurance: function(frm) {
        calculate_totals(frm);
    },
    tax_rate: function(frm) {
        calculate_totals(frm);
    },
    agent_rate: function(frm) {
        calculate_totals(frm);
    }
});

// Отслеживаем изменения в таблице Deal Service Item (где цена = rate)
frappe.ui.form.on('Deal Service Item', {
    rate: function(frm, cdt, cdn) {
        calculate_services_total(frm);
    },
    service: function(frm, cdt, cdn) {
        // Задержка, чтобы Fetch From успел записать значение в rate
        setTimeout(() => {
            calculate_services_total(frm);
        }, 400);
    },
    qty: function(frm, cdt, cdn) {
        calculate_services_total(frm);
    },
    services_add: function(frm) {
        calculate_services_total(frm);
    },
    services_remove: function(frm) {
        calculate_services_total(frm);
    }
});

// 1. Подсчёт суммы по таблице услуг
function calculate_services_total(frm) {
    let total_services = 0;
    
    let rows = frm.doc.services || [];
    rows.forEach(row => {
        // Берем считываемое значение из поля rate
        let price = flt(row.rate) || flt(row.price) || flt(row.amount) || 0;
        let qty = flt(row.qty) || 1;
        total_services += price * qty;
    });

    frm.set_value('total_paid_services', total_services);
    frm.refresh_field('total_paid_services');
    
    calculate_totals(frm);
}

// 2. Полный финансовый расчёт сделки
function calculate_totals(frm) {
    let dev = flt(frm.doc.paid_by_developer);
    let bank = flt(frm.doc.paid_by_bank);
    let ins = flt(frm.doc.paid_by_insurance);
    let services = flt(frm.doc.total_paid_services);

    // Выплаты от партнеров
    let total_comm = dev + bank + ins;
    frm.set_value('total_commission', total_comm);

    // Валовая выручка (Партнеры + Услуги)
    let gross_revenue = total_comm + services;
    frm.set_value('total_gross_revenue', gross_revenue);

    // Налог
    let tax_pct = flt(frm.doc.tax_rate);
    let tax_amt = gross_revenue * (tax_pct / 100);
    frm.set_value('tax_amount', tax_amt);

    // Чистая КВ (Валовая выручка - Налог)
    let net_comm = gross_revenue - tax_amt;
    frm.set_value('net_commission', net_comm);

    // Комиссия Агента
    let agent_pct = flt(frm.doc.agent_rate);
    let agent_comm = net_comm * (agent_pct / 100);
    frm.set_value('agent_commission', agent_comm);

    // Доход компании
    let company_comm = net_comm - agent_comm;
    frm.set_value('company_commission', company_comm);
}
